import json,glob,os
be=[]
for f in glob.glob('$TD/*/result.json'):
    try: r=json.load(open(f))
    except: continue
    a=r.get('agent') or {}
    if a.get('exit_reason')=='budget_exceeded':
        be.append((os.path.dirname(f), r.get('task_id'), a.get('steps')))
for d,tid,steps in be:
    mf=os.path.join(d,'messages.json')
    if not os.path.exists(mf): 
        print(tid, steps, 'NOMSG'); continue
    m=json.load(open(mf))
    # count consecutive loop-warning appearances
    warns=sum(1 for x in m if x['role']=='tool' and isinstance(x.get('content'),str) and 'LoopDetection' in x['content'])
    # count how many distinct tool commands vs total
    calls=[]
    for x in m:
        for t in (x.get('tool_calls') or []):
            calls.append(t.get('function',{}).get('arguments',''))
    print(tid, 'steps=',steps,'msgs=',len(m),'loopwarns=',warns,'calls=',len(calls),'distinct=',len(set(calls)))
"

